function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 30) return 'n is between 1 and 30.';
  if (!Number.isInteger(k) || k < 1 || k > 2 ** (n - 1)) return 'k is between 1 and 2^(n - 1), the length of row n.';
  return null;
}

