function kthGrammar(n, k) {
  let position = k - 1;
  let symbol = 0;
  while (position > 0) {
    symbol ^= 1;
    position &= position - 1;
  }
  return symbol;
}

brute:
function kthGrammar(n, k) {
  // Short rows are written out literally; a longer row's symbol comes from its parent in the row above.
  if (n <= 16) {
    let row = '0';
    for (let r = 1; r < n; r++) row = row.replace(/[01]/g, symbol => (symbol === '0' ? '01' : '10'));
    return Number(row[k - 1]);
  }
  const parent = kthGrammar(n - 1, Math.ceil(k / 2));
  return k % 2 === 1 ? parent : 1 - parent;
}

