function generate(rand, size) {
  const n = size === 'large' ? 25 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 10);
  const length = 2 ** (n - 1);
  const roll = rand();
  const k = roll < 0.1 ? 1 : roll < 0.2 ? length : 1 + Math.floor(rand() * length);
  return [n, k];
}
